function moved(piece, dr, dc) {
  return { type: piece.type, matrix: piece.matrix, row: piece.row + dr, col: piece.col + dc };
}

// Cells the current piece would occupy after a hard drop.
function ghostCells() {
  if (!state.current) return [];
  var ghost = state.current;
  while (fits(moved(ghost, 1, 0))) ghost = moved(ghost, 1, 0);
  return pieceCells(ghost);
}

